static NSString *AcapeDecodeRevealBytes(const uint8_t *bytes, NSUInteger length) {
    if (!bytes || length == 0) {
        return @"";
    }
    NSMutableString *result = [NSMutableString stringWithCapacity:length];
    for (NSUInteger i = 0; i < length; i++) {
        unichar character = bytes[i] ^ kAcapeRevealKey[i % kAcapeRevealKeyLen];
        [result appendFormat:@"%C", character];
    }
    return result.copy;
}

